#include <string>

using namespace std;

class Solution {
public:
    string maximumBinaryString(string binary) {
        int n = binary.size(), count0 = 0, first0 = -1;
        for (int i = 0; i < n; ++i) {
            if (binary[i] == '0') {
                if (first0 == -1) first0 = i;
                ++count0;
            }
        }
        if (count0 <= 1) return binary;
        string res(n, '1');
        res[first0 + count0 - 1] = '0';
        return res;
    }
};
